const pct=(n,d=1)=>Number.isFinite(n)?`${fmt(n,d)} %`:"—";
const fmtCompact=(n,d=1)=>Number.isFinite(n)?new Intl.NumberFormat("fr-FR",{notation:"compact",maximumFractionDigits:d}).format(n):"—";
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const isMissing=v=>v===null||v===undefined||String(v).trim()===""||["na","n/a","null","undefined","nan","-"].includes(String(v).trim().toLowerCase());
