function setLoading(show,title="Analyse en cours",text="Préparation des indicateurs et des modèles statistiques…"){$("loadingTitle").textContent=title;$("loadingText").textContent=text;$("loadingOverlay").classList.toggle("show",show)}
function syncCustomInputs(){if(!$('customPrimary'))return;$('customPrimary').value=activePalette.primary;$('customPrimary2').value=activePalette.primary2;$('customAccent').value=activePalette.accent;$('customAccent2').value=activePalette.accent2;$('customBg').value=activePalette.bg||'#eef2f7'}
function renderPalettePreview(){const preview=$('palettePreview');if(!preview)return;const colors=[activePalette.primary,activePalette.primary2,activePalette.accent,activePalette.accent2,...activePalette.colors.slice(2,4)];[...preview.children].forEach((el,i)=>el.style.background=colors[i]||activePalette.accent)}
function applyPalette(name,rerender=true){if(name==='custom')updateCustomPalette(false);else activePalette=palettes[name]||palettes.onyx;const r=document.documentElement.style;r.setProperty('--primary',activePalette.primary);r.setProperty('--primary-2',activePalette.primary2);r.setProperty('--accent',activePalette.accent);r.setProperty('--accent-2',activePalette.accent2);r.setProperty('--bg',activePalette.bg||'#eef2f7');if(name!=='custom')syncCustomInputs();renderPalettePreview();if(rerender&&state.data.length)renderAll()}
function updateCustomPalette(rerender=true){const p=$('customPrimary')?.value||'#111827',p2=$('customPrimary2')?.value||'#1f2937',a=$('customAccent')?.value||'#7c3aed',a2=$('customAccent2')?.value||'#06b6d4',bg=$('customBg')?.value||'#eef2f7';palettes.custom={name:'Palette personnalisée',primary:p,primary2:p2,accent:a,accent2:a2,bg,colors:[a,a2,p,p2,'#2f80ed','#27ae60','#f2c94c','#eb5757']};activePalette=palettes.custom;if($('palette'))$('palette').value='custom';const r=document.documentElement.style;r.setProperty('--primary',p);r.setProperty('--primary-2',p2);r.setProperty('--accent',a);r.setProperty('--accent-2',a2);r.setProperty('--bg',bg);renderPalettePreview();if(rerender&&state.data.length)renderAll()}
function plotLayout(title=""){return{title:{text:title,font:{size:14}},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"rgba(0,0,0,0)",font:{family:"Inter,Segoe UI,sans-serif",color:"#334155",size:11},margin:{l:55,r:25,t:title?55:25,b:55},hoverlabel:{bgcolor:"#111827",font:{color:"#fff"}},xaxis:{gridcolor:"#e7edf5",zerolinecolor:"#d7dee8"},yaxis:{gridcolor:"#e7edf5",zerolinecolor:"#d7dee8"},colorway:activePalette.colors}}
