function emptyPlot(id,msg){$(id).innerHTML=`<div class="empty">${esc(msg)}</div>`}

function smartNumber(v){if(isMissing(v))return null;if(typeof v==="number"&&Number.isFinite(v))return v;let s=String(v).trim().replace(/\s/g,"");if(/^[-+]?\d{1,3}(,\d{3})+(\.\d+)?$/.test(s))s=s.replace(/,/g,"");else if(/^[-+]?\d+(,\d+)$/.test(s)&&!s.includes("."))s=s.replace(",",".");s=s.replace(/[%$€£¥₽₺₦₲]/g,"");const n=Number(s);return Number.isFinite(n)?n:null}
function smartDate(v){if(isMissing(v))return null;if(v instanceof Date&&!isNaN(v))return v;const s=String(v).trim();if(/^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}(?:[T\s].*)?$/.test(s)){const d=new Date(s.replace(/\//g,"-"));return isNaN(d)?null:d}const m=s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})(?:[ T].*)?$/);if(m){let y=Number(m[3]);if(y<100)y+=2000;const d=new Date(y,Number(m[2])-1,Number(m[1]));return isNaN(d)?null:d}if(/^(19|20)\d{2}$/.test(s))return new Date(Number(s),0,1);if(/\b(19|20)\d{2}\b/.test(s)&&/[A-Za-zÀ-ÿ]/.test(s)){const d=new Date(s);return isNaN(d)?null:d}return null}
function normalizeRows(rows){const clean=(rows||[]).filter(r=>r&&typeof r==="object");const cols=[...new Set(clean.flatMap(r=>Object.keys(r).map(k=>String(k).trim()||"Sans_nom")))];return clean.map(r=>Object.fromEntries(cols.map(c=>[c,r[c]??""])))}
function quantile(sorted,q){if(!sorted.length)return NaN;const p=(sorted.length-1)*q,b=Math.floor(p),rest=p-b;return sorted[b+1]!==undefined?sorted[b]+rest*(sorted[b+1]-sorted[b]):sorted[b]}
const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:NaN;
function variance(a){if(a.length<2)return 0;const m=mean(a);return a.reduce((s,v)=>s+(v-m)**2,0)/(a.length-1)}
const sd=a=>Math.sqrt(variance(a));
function median(a){const s=[...a].sort((x,y)=>x-y);return quantile(s,.5)}
function skew(a){if(a.length<3)return 0;const m=mean(a),s=sd(a);return s?a.reduce((z,v)=>z+((v-m)/s)**3,0)/a.length:0}
function kurt(a){if(a.length<4)return 0;const m=mean(a),s=sd(a);return s?a.reduce((z,v)=>z+((v-m)/s)**4,0)/a.length-3:0}
function rankArray(a){const indexed=a.map((v,i)=>({v,i})).sort((x,y)=>x.v-y.v),r=Array(a.length);for(let i=0;i<indexed.length;){let j=i;while(j+1<indexed.length&&indexed[j+1].v===indexed[i].v)j++;const rr=(i+j+2)/2;for(let k=i;k<=j;k++)r[indexed[k].i]=rr;i=j+1}return r}
function pearson(x,y){if(x.length<3)return NaN;const mx=mean(x),my=mean(y),sx=Math.sqrt(x.reduce((s,v)=>s+(v-mx)**2,0)),sy=Math.sqrt(y.reduce((s,v)=>s+(v-my)**2,0));if(!sx||!sy)return 0;return x.reduce((s,v,i)=>s+(v-mx)*(y[i]-my),0)/(sx*sy)}
function linearRegression(x,y){if(x.length<3)return null;const mx=mean(x),my=mean(y),den=x.reduce((s,v)=>s+(v-mx)**2,0);if(!den)return null;const slope=x.reduce((s,v,i)=>s+(v-mx)*(y[i]-my),0)/den,intercept=my-slope*mx;const pred=x.map(v=>intercept+slope*v),sst=y.reduce((s,v)=>s+(v-my)**2,0),sse=y.reduce((s,v,i)=>s+(v-pred[i])**2,0);return{slope,intercept,r2:sst?1-sse/sst:0,n:x.length,pred}}

const ROLE_META={
  identifier:{label:"Identifiant",short:"ID",utility:"Clé d'unicité, dédoublonnage et suivi des entités.",priority:100},
  revenue:{label:"Revenu / chiffre d'affaires",short:"REV",utility:"KPI financier principal : somme, moyenne, croissance et contribution.",priority:98},
  volume:{label:"Volume / quantité",short:"VOL",utility:"Mesure de l'activité : quantité, effectif, dossiers ou transactions.",priority:96},
  amount:{label:"Montant financier",short:"€",utility:"Mesure monétaire à agréger et comparer dans le temps.",priority:92},
  cost:{label:"Coût / dépense",short:"CST",utility:"Analyse des charges, de l'efficience et des écarts.",priority:91},
  result:{label:"Résultat / réalisation",short:"RÉS",utility:"Mesure des réalisations et de la performance observée.",priority:89},
  target:{label:"Objectif / cible",short:"OBJ",utility:"Référence pour calculer l'écart et le taux d'atteinte.",priority:88},
  rate:{label:"Taux / ratio",short:"%",utility:"Indicateur relatif à analyser en niveau et en évolution.",priority:86},
  date:{label:"Date / période",short:"DATE",utility:"Axe temporel pour tendances, saisonnalité et prévisions.",priority:95},
  duration:{label:"Délai / durée",short:"DÉL",utility:"Mesure de rapidité, retard, ancienneté ou cycle de traitement.",priority:84},
  status:{label:"Statut / état",short:"STAT",utility:"Dimension de suivi des étapes, résultats et situations.",priority:81},
  geography:{label:"Géographie / site",short:"GÉO",utility:"Dimension territoriale pour comparer les zones et unités.",priority:79},
  score:{label:"Score / qualité",short:"SCR",utility:"Mesure synthétique de qualité, satisfaction ou risque.",priority:78},
  entity:{label:"Entité / dimension",short:"DIM",utility:"Dimension de regroupement : client, produit, agence, service ou projet.",priority:74},
  category:{label:"Catégorie",short:"CAT",utility:"Dimension de segmentation et de comparaison.",priority:70},
  description:{label:"Information descriptive",short:"TXT",utility:"Contexte qualitatif, commentaire ou description.",priority:45},
  empty:{label:"Non renseigné",short:"—",utility:"Variable vide ou inutilisable sans correction.",priority:5}
};
function normalizeSemanticName(value){return String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}
function roleLabel(key){return ROLE_META[key]?.label||ROLE_META.description.label}

const VARIABLE_FAMILIES={
  identity:{label:"Clés et identifiants",short:"ID",description:"Clés de suivi, dédoublonnage et rapprochement des entités.",color:"#7c3aed",order:1,roles:["identifier"]},
  finance:{label:"Mesures financières",short:"FIN",description:"Revenus, chiffre d’affaires, montants, coûts et dépenses.",color:"#0f766e",order:2,roles:["revenue","amount","cost"]},
  activity:{label:"Volumes et activité",short:"VOL",description:"Quantités, effectifs, dossiers, transactions, durées et délais.",color:"#2563eb",order:3,roles:["volume","duration"]},
  time:{label:"Temps et périodes",short:"DATE",description:"Dates nécessaires aux tendances, comparaisons et prévisions.",color:"#0891b2",order:4,roles:["date"]},
  performance:{label:"Pilotage et performance",short:"KPI",description:"Objectifs, réalisations, taux, scores, statuts et niveaux de performance.",color:"#d97706",order:5,roles:["target","result","rate","score","status"]},
  dimensions:{label:"Axes de comparaison",short:"DIM",description:"Clients, produits, agences, services, catégories, territoires ou projets.",color:"#16a34a",order:6,roles:["entity","geography","category"]},
  qualitative:{label:"Informations qualitatives",short:"TXT",description:"Commentaires, descriptions, motifs, remarques et autres éléments contextuels.",color:"#be185d",order:7,roles:["description"]},
  technical:{label:"Variables à fiabiliser",short:"TEC",description:"Colonnes vides, peu exploitables ou nécessitant une clarification métier.",color:"#64748b",order:8,roles:["empty"]}
};
function variableFamilyKey(column){const rk=state.roleKeys[column]||"description";return Object.keys(VARIABLE_FAMILIES).find(k=>VARIABLE_FAMILIES[k].roles.includes(rk))||"qualitative"}
function variableFamily(column){return VARIABLE_FAMILIES[variableFamilyKey(column)]}
function aggregationSuggestion(column){const rk=state.roleKeys[column]||"description",type=state.types[column];if(rk==="identifier")return"Nombre distinct";if(["revenue","amount","cost","volume","result"].includes(rk))return"Somme + moyenne";if(["target","rate","score"].includes(rk))return"Moyenne pondérée";if(rk==="duration")return"Moyenne + médiane";if(rk==="date")return"Min / max + période";if(rk==="status")return"Fréquence + taux";if(["entity","geography","category"].includes(rk))return"Répartition / classement";if(type==="numérique")return"Distribution";return"Fréquence / texte"}
function decisionUse(column){const rk=state.roleKeys[column]||"description";if(rk==="identifier")return"Clé de suivi";if(rk==="revenue")return"KPI financier central";if(rk==="amount")return"Valeur monétaire";if(rk==="cost")return"Efficience / charges";if(rk==="volume")return"Niveau d’activité";if(rk==="date")return"Évolution temporelle";if(rk==="target")return"Référence de performance";if(rk==="result")return"Réalisation observée";if(rk==="rate")return"Performance relative";if(rk==="score")return"Qualité / risque";if(rk==="status")return"Suivi du cycle";if(["entity","geography","category"].includes(rk))return"Segmentation";if(rk==="duration")return"Rapidité / délai";return"Contexte qualitatif"}
function structuredVariableGroups(){const groups={};for(const c of state.columns){const key=variableFamilyKey(c);(groups[key]??=[]).push(c)}for(const key of Object.keys(groups))groups[key].sort((a,b)=>rolePriority(b)-rolePriority(a)||a.localeCompare(b,"fr"));return Object.entries(groups).sort((a,b)=>VARIABLE_FAMILIES[a[0]].order-VARIABLE_FAMILIES[b[0]].order)}
function variableQualityLabel(column){const complete=100-(state.missing[column]||0);return complete>=95?"Très complète":complete>=80?"Exploitable":complete>=60?"À surveiller":"Critique"}
function roleUtility(column){return ROLE_META[state.roleKeys[column]]?.utility||ROLE_META.description.utility}
function rolePriority(column){const key=state.roleKeys[column]||"description",base=ROLE_META[key]?.priority||40,primary=state.business&&[state.business.primaryId,state.business.primaryRevenue,state.business.primaryVolume,state.business.primaryFinancial,state.business.primaryDate,state.business.primaryDimension,state.business.primaryStatus].includes(column);return base+(primary?12:0)}
function importanceInfo(column){const p=rolePriority(column);return p>=105?{label:"Critique",className:"critical"}:p>=90?{label:"Élevée",className:"high"}:p>=70?{label:"Utile",className:"useful"}:{label:"Contexte",className:"context"}}
function detectRoleDetails(name,type,values=[],uniqueRatio=0){
  const n=normalizeSemanticName(name), numeric=type==="numérique";
  const test=r=>r.test(n);
  let key="description",confidence=.55,reason="Rôle inféré à partir du type et du nom.";
  if(test(/\b(id|identifiants?|identifier|uuid|matricule|reference|ref|code|numero|number|nif|cin|passport|passeport)\b/)||test(/\b(client|customer|police|policy|facture|invoice|transaction|dossier|beneficiaire|employe|employee|produit|product|projet|project|compte|account|contrat|contract)\s+(id|code|num|numero|number|no|ref)\b/)){key="identifier";confidence=.96;reason="Le nom indique une clé, un code ou un numéro d'identification."}
  else if(test(/\b(date|jour|day|mois|month|annee|year|periode|period|timestamp|created|creation|updated|echeance|deadline)\b/)||type==="date"){key="date";confidence=.95;reason="La variable structure les observations dans le temps."}
  else if(test(/\b(nombre|nb|count|quantites?|quantity|quantities|qte|volumes?|effectifs?|unites|units|dossiers|transactions|commandes|orders|beneficiaires|participants|visites|visits)\b/)){key="volume";confidence=.93;reason="Le nom correspond à une mesure d'activité ou de quantité."}
  else if(test(/\b(chiffre d affaires|chiffre affaires|ca|revenus?|revenues?|income|incomes|recettes?|ventes?|sales|encaissements?|primes?|cotisations?|turnover)\b/)){key="revenue";confidence=.94;reason="Le nom correspond à une mesure de revenu ou de ventes."}
  else if(test(/\b(couts?|costs?|depenses?|expenses?|charges?|frais|achats?|decaissements?)\b/)){key="cost";confidence=.92;reason="Le nom correspond à un coût, une dépense ou une charge."}
  else if(test(/\b(montants?|amounts?|valeurs?|values?|soldes?|balances?|total|totaux|budgets?|budgetaire|financements?|funding)\b/)){key="amount";confidence=.86;reason="Le nom indique une valeur ou un montant financier générique."}
  else if(test(/\b(objectif|objectifs|cible|cibles|target|targets|prevision|forecast|planifie|planned)\b/)){key="target";confidence=.91;reason="La variable représente une cible, un objectif ou une prévision."}
  else if(test(/\b(realisation|realisations|resultat|resultats|actual|atteint|achieved|performance|output|outcome)\b/)){key="result";confidence=.88;reason="La variable représente un résultat ou une réalisation observée."}
  else if(test(/\b(taux|rates?|ratios?|pourcentages?|percentages?|pct|parts?|marges?|margins?|conversion|rendements?|yield)\b/)){key="rate";confidence=.90;reason="Le nom correspond à un taux, un ratio ou un pourcentage."}
  else if(test(/\b(delais?|durees?|durations?|retards?|delays?|anciennete|age|jours|days|heures|hours|minutes)\b/)){key="duration";confidence=.88;reason="La variable mesure une durée, un délai ou un retard."}
  else if(test(/\b(statuts?|status|etats?|states?|phases?|situations?|decision|issue|result)\b/)){key="status";confidence=.87;reason="La variable décrit un état ou une étape de traitement."}
  else if(test(/\b(regions?|zones?|departements?|communes?|villes?|city|cities|pays|countries?|territoires?|sites?|agences?|branches?|bureaux|bureau|offices?|localisations?|locations?)\b/)){key="geography";confidence=.85;reason="La variable permet une analyse territoriale ou par unité."}
  else if(test(/\b(scores?|notes?|indices?|index|qualite|quality|satisfaction|risques?|risks?)\b/)){key="score";confidence=.84;reason="La variable synthétise une qualité, une satisfaction ou un risque."}
  else if(test(/\b(client|customer|produit|product|service|fournisseur|supplier|employe|employee|projet|project|programme|program|departement|department|categorie|category|segment|canal|channel)\b/)){key="entity";confidence=.80;reason="La variable représente une entité ou une dimension métier."}
  else if(type==="catégorielle"){key="category";confidence=.70;reason="La variable peut servir de dimension de comparaison ou de segmentation."}
  else if(type==="numérique"){key="result";confidence=.58;reason="Variable quantitative sans libellé métier explicite; traitée comme mesure générique."}
  else if(type==="identifiant"){key="identifier";confidence=.88;reason="La structure et l'unicité indiquent une clé potentielle."}
  if(key==="identifier"&&uniqueRatio<.25&&type!=="identifiant"){confidence=Math.min(confidence,.70);reason+=" Son faible taux d'unicité doit être vérifié."}
  if(["revenue","cost","amount","volume","result","target","rate","duration","score"].includes(key)&&!numeric){confidence=Math.min(confidence,.68);reason+=" Le format non numérique limite les calculs tant qu'il n'est pas converti."}
  return{key,label:roleLabel(key),confidence,reason}
}

