function dist(a,b){return Math.sqrt(a.reduce((s,v,i)=>s+(v-b[i])**2,0))}
function kmeans(points,k,iterations=80){const sorted=[...points].map((p,i)=>({p,i})).sort((a,b)=>a.p[0]-b.p[0]);let centroids=Array.from({length:k},(_,j)=>[...sorted[Math.floor((j+.5)*sorted.length/k)].p]),labels=Array(points.length).fill(-1);for(let it=0;it<iterations;it++){let changed=false;const next=points.map((p,i)=>{let best=0,bd=Infinity;centroids.forEach((c,j)=>{const d=dist(p,c);if(d<bd){bd=d;best=j}});if(best!==labels[i])changed=true;return best});labels=next;for(let j=0;j<k;j++){const g=points.filter((_,i)=>labels[i]===j);if(g.length)centroids[j]=centroids[j].map((_,d)=>mean(g.map(p=>p[d])))}if(!changed&&it>2)break}return{labels,centroids}}
function silhouette(points,labels,k){const idx=points.length>700?Array.from({length:700},(_,i)=>Math.floor(i*points.length/700)):points.map((_,i)=>i);const scores=[];for(const i of idx){const own=labels[i];const same=[],other=Array.from({length:k},()=>[]);for(let j=0;j<points.length;j++){if(i===j)continue;const d=dist(points[i],points[j]);if(labels[j]===own)same.push(d);else other[labels[j]].push(d)}const a=same.length?mean(same):0,b=Math.min(...other.filter(g=>g.length).map(mean));scores.push(Math.max(a,b)?(b-a)/Math.max(a,b):0)}return mean(scores)}

function audienceLabel(){return{direction:"Direction générale",decideurs:"Décideurs publics",bailleurs:"Bailleurs et partenaires",management:"Management opérationnel",analystes:"Analystes / Data scientists"}[$("audience").value]}
function objectiveLabel(){return{general:"diagnostic général",performance:"performance",finance:"finance et efficience",operations:"opérations",quality:"qualité et conformité",impact:"impact et résultats"}[$("objective").value]}
function depthLabel(){return{essential:"essentiel",advanced:"approfondi",expert:"expert"}[$("depth").value]}
function analysisFacts(){const num=state.columns.filter(c=>state.types[c]==="numérique"),cat=state.columns.filter(c=>state.types[c]==="catégorielle"),dates=state.columns.filter(c=>state.types[c]==="date"),worst=[...state.columns].sort((a,b)=>state.missing[b]-state.missing[a])[0],corr=state.correlations[0],trend=state.timeSeries.find(t=>t.metric===state.business?.primaryRevenue)||state.timeSeries.find(t=>t.metric===state.business?.primaryVolume)||state.timeSeries[0];return{num,cat,dates,worst,corr,trend,business:state.business}}
function executiveNarrative(){const f=analysisFacts(),b=f.business,q=state.quality.score,missing=f.worst?state.missing[f.worst]:0,obj=objectiveLabel();let opening=`Le fichier « ${state.fileName} » contient ${fmt(state.data.length,0)} enregistrements et ${state.columns.length} variables. Le moteur a priorisé ${b?.primaryId?`l'identifiant « ${b.primaryId} »`:"aucune clé d'identification fiable"}, ${b?.primaryRevenue?`le revenu « ${b.primaryRevenue} »`:"aucune variable de revenu explicite"} et ${b?.primaryVolume?`le volume « ${b.primaryVolume} »`:"le nombre de lignes comme volume de référence"}.`;let metrics=[];if(b?.primaryRevenue)metrics.push(`revenu total ${fmt(b.revenueTotal,2)}`);else if(b?.primaryFinancial)metrics.push(`montant total ${fmt(b.financialTotal,2)}`);metrics.push(`volume ${fmt(b?.volumeTotal??state.data.length,2)}`);if(b?.range)metrics.push(`période ${b.range.label}`);let quality=`Le score de qualité atteint ${pct(q,1)}, ce qui rend la base ${q>=85?"solide":q>=70?"globalement exploitable":q>=50?"fragile":"insuffisamment fiable"} pour une analyse de ${obj}.`;let risk=missing>10?`La principale réserve concerne « ${f.worst} », dont ${pct(missing,1)} des valeurs sont manquantes.`:"Aucune variable ne concentre un déficit critique de complétude.";let rel=f.corr&&Math.abs(f.corr.r)>=.5?`Une relation notable est observée entre « ${f.corr.a} » et « ${f.corr.b} » (r = ${fmt(f.corr.r,2)}), sans permettre de conclure à une causalité.`:"Les relations numériques disponibles ne suffisent pas, seules, à expliquer la performance.";return`${opening} Les principaux ordres de grandeur sont : ${metrics.join(" ; ")}. ${quality} ${risk} ${rel}` }
function buildRecommendations(){const rec=[],f=analysisFacts(),q=state.quality.score;const add=(priority,title,description,impact,effort,horizon,owner)=>rec.push({priority,title,description,impact,effort,horizon,owner});if(q<75)add("Priorité critique","Mettre en place un plan de fiabilisation","Corriger les valeurs manquantes, harmoniser les formats et documenter les règles de gestion avant toute utilisation décisionnelle récurrente.",5,3,"0–30 jours","Data owner / Métiers");else add("Priorité haute","Institutionnaliser le contrôle qualité","Transformer les contrôles actuels en règles automatiques avec seuils d'alerte, responsables et journal des corrections.",4,2,"0–60 jours","Gouvernance des données");if(state.duplicates>0)add("Priorité haute","Traiter les doublons","Définir une clé d'unicité, distinguer les doublons techniques des répétitions métier et sécuriser le processus d'alimentation.",4,2,"0–30 jours","Équipe data");if(state.anomalies.length/state.data.length>.03)add("Priorité haute","Auditer les observations atypiques",`Examiner en priorité les ${Math.min(state.anomalies.length,50)} lignes les plus atypiques et documenter les corrections ou justifications.`,4,2,"0–30 jours","Contrôle / Métiers");if(f.corr&&Math.abs(f.corr.r)>.65)add("Priorité stratégique","Exploiter la relation la plus structurante",`Tester opérationnellement le lien entre « ${f.corr.a} » et « ${f.corr.b} » par segmentation, validation métier et modèle contrôlé.`,5,3,"30–90 jours","Direction / Analystes");if(f.trend)add("Priorité stratégique","Piloter la tendance temporelle",`Mettre sous surveillance « ${f.trend.metric} » : variation de ${pct(f.trend.change,1)} sur la période et volatilité estimée à ${pct(f.trend.volatility,1)}.`,4,2,"Immédiat","Pilotage de la performance");const b=state.business;if(!b?.primaryId)add("Priorité haute","Créer un identifiant principal","Ajouter une clé stable et unique pour chaque entité ou événement afin de sécuriser le dédoublonnage, les cohortes et le suivi longitudinal.",5,2,"0–30 jours","Data owner / Métiers");if(!b?.primaryRevenue&&!b?.primaryFinancial)add("Priorité haute","Formaliser la mesure financière principale","Nommer et documenter une colonne de revenu, montant ou dépense avec unité, devise et règle d’agrégation.",4,2,"0–30 jours","Finance / Data owner");if(!b?.primaryDate)add("Priorité haute","Ajouter une date de référence fiable","Créer une date normalisée par enregistrement pour activer les tendances, comparaisons mensuelles et prévisions.",5,2,"0–30 jours","Équipe source");if(!b?.primaryVolume)add("Priorité moyenne","Définir le volume opérationnel","Ajouter une quantité ou un nombre d’activités explicite plutôt que d’utiliser uniquement le nombre de lignes.",4,2,"30–60 jours","Opérations");const obj=$("objective").value;if(obj==="finance")add("Priorité stratégique","Relier ressources, coûts et résultats","Construire un tableau d'efficience combinant dépenses, volumes, résultats et écarts budgétaires, avec analyse des unités les plus performantes.",5,3,"30–90 jours","Finance / Contrôle de gestion");if(obj==="impact")add("Priorité stratégique","Renforcer la mesure d'impact","Distinguer réalisations, résultats et effets; ajouter une situation de référence, des cibles et des dimensions de désagrégation pertinentes.",5,4,"60–180 jours","Suivi-évaluation");if(obj==="operations")add("Priorité haute","Déployer un cockpit opérationnel","Suivre les volumes, délais, écarts et statuts avec seuils, responsables et routines de revue hebdomadaire.",4,3,"30–60 jours","Opérations");if(obj==="performance")add("Priorité stratégique","Formaliser un arbre de performance","Relier objectifs, inducteurs, KPI de résultat et KPI d'alerte afin d'éviter un pilotage fondé sur des indicateurs isolés.",5,3,"30–90 jours","Direction de la performance");if(obj==="quality")add("Priorité critique","Établir un référentiel de conformité","Définir les règles de validation, les seuils d'acceptation, les preuves attendues et le circuit de traitement des écarts.",5,3,"0–60 jours","Qualité / Conformité");const aud=$("audience").value;if(aud==="bailleurs")add("Priorité de redevabilité","Documenter les preuves et limites","Associer chaque indicateur à sa source, sa méthode de calcul, sa fréquence, son responsable et son niveau de fiabilité.",5,2,"0–60 jours","Suivi-évaluation");if(aud==="decideurs")add("Priorité d'équité","Désagréger les résultats","Comparer les résultats par territoire, population ou catégorie pertinente afin d'identifier les écarts masqués par les moyennes globales.",5,3,"30–90 jours","Planification / Statistiques");if(aud==="analystes")add("Priorité technique","Valider les hypothèses des modèles","Compléter l'exploration par diagnostics de résidus, validation croisée, tests de robustesse et analyse de sensibilité.",4,4,"30–120 jours","Data science");add("Amélioration continue","Créer un dictionnaire de données","Formaliser la définition, le type, l'unité, la source et la règle de calcul de chaque variable critique.",4,2,"0–60 jours","Data steward");return rec.slice(0,$("depth").value==="essential"?6:$("depth").value==="advanced"?9:12)}

async function onyxAnalyzeDataCore(rows,fileName="Données"){setLoading(true);await new Promise(r=>setTimeout(r,60));const start=performance.now();try{const data=normalizeRows(rows);if(!data.length)throw new Error("Le fichier ne contient aucune ligne exploitable.");state.data=data;state.columns=Object.keys(data[0]);state.fileName=fileName;const inferred=inferTypes(data,state.columns);state.types=inferred.types;state.roles=inferred.roles;state.roleKeys=inferred.roleKeys;state.roleConfidence=inferred.roleConfidence;state.roleReasons=inferred.roleReasons;const cs=computeStats(data,state.columns,state.types);Object.assign(state,cs);state.duplicates=countDuplicates(data,state.columns);state.business=buildBusinessProfile();const nums=state.columns.filter(c=>state.types[c]==="numérique");state.anomalies=computeAnomalies(data,nums,state.stats);const corr=computeCorrelations(data,nums);state.correlations=corr.pear;state.spearman=corr.spear;state.cramer=computeCramer(data,state.columns.filter(c=>state.types[c]==="catégorielle"));state.regressions=computeRegressions(data,state.correlations);state.timeSeries=computeTimeSeries();state.quality=computeQuality(data,state.columns,nums);state.confidence=computeConfidence();state.pca=computePCA();state.clusters=null;state.recommendations=buildRecommendations();state.analysisMs=performance.now()-start;renderAll();$("fileStatus").textContent=`${fileName} analysé avec succès.`;$("analysisTime").textContent=`Diagnostic métier et statistique en ${fmt(state.analysisMs,0)} ms`;$("statusDot").classList.add("ready");["reportBtn","pdfBtn","htmlBtn","resetBtn","clusterBtn"].forEach(id=>$(id).disabled=false);const b=state.business;$("sideStatus").innerHTML=`<strong>${esc(fileName)}</strong><br>${fmt(data.length,0)} enregistrements · ${state.columns.length} variables<br>${b.primaryId?`ID : ${esc(b.primaryId)}`:"Aucun ID détecté"} · ${b.primaryRevenue?`Revenu : ${esc(b.primaryRevenue)}`:b.primaryFinancial?`Montant : ${esc(b.primaryFinancial)}`:"Aucun revenu détecté"}<br>${b.primaryVolume?`Volume : ${esc(b.primaryVolume)}`:"Volume = lignes"}${b.primaryDate?` · Date : ${esc(b.primaryDate)}`:""}`;setLoading(false)}catch(e){setLoading(false);showError(e.message||"Erreur d'analyse.")}}
function onyxRenderAllCore(){if(!state.data.length)return;renderKPIs();renderSelects();renderOverview();renderExecutive();renderQuality();renderDescriptive();renderPeriodicStatistics();renderRelationships();renderTemporal();renderPCA();renderRecommendations();renderData()}
function renderKPIs(){const q=state.quality,b=state.business||buildBusinessProfile(),financial=b.primaryRevenue?b.revenueTotal:b.financialTotal;$("kpiRows").textContent=fmtCompact(state.data.length,1);$("kpiRowsNote").textContent=`${state.columns.length} variables analysées`;$("kpiCols").textContent=b.primaryId?fmtCompact(b.idDistinct,1):"Non détecté";$("kpiColsNote").textContent=b.primaryId?`${b.primaryId} · unicité ${pct(b.idUniqueness,0)}`:"Ajoutez une colonne ID, code ou référence";$("kpiComplete").textContent=Number.isFinite(financial)?fmtCompact(financial,1):"Non détecté";$("kpiCompleteNote").textContent=b.primaryRevenue?`${b.primaryRevenue} · revenu total`:b.primaryFinancial?`${b.primaryFinancial} · montant total`:"Aucune mesure financière explicite";$("kpiQuality").textContent=fmtCompact(b.volumeTotal,1);$("kpiQualityNote").textContent=b.primaryVolume?`${b.primaryVolume} · volume cumulé`:"Nombre de lignes utilisé comme volume";$("kpiAnomalies").textContent=b.range?b.range.label:"Non détectée";$("kpiAnomaliesNote").textContent=b.primaryDate?`${b.primaryDate} · ${b.range.detail}`:"Ajoutez une variable date";$("kpiConfidence").textContent=`${fmt(q.score,0)}/100`;$("kpiConfidenceNote").textContent=`Complétude ${pct(q.completeness,0)} · ${state.anomalies.length} anomalie(s)`;$("sideConfidence").textContent=pct(state.confidence,0);$("sideConfidenceBar").style.width=`${state.confidence}%`;$("sideConfidenceText").textContent=state.confidence>=85?"Élevée":state.confidence>=70?"Bonne":state.confidence>=55?"Modérée":"Limitée"}
function options(id,items,selected){const el=$(id);el.innerHTML=items.length?items.map(x=>`<option value="${esc(x)}" ${x===selected?"selected":""}>${esc(x)}</option>`).join(""):"<option>Aucune variable</option>"}
function renderSelects(){const nums=state.columns.filter(c=>state.types[c]==="numérique"),cats=state.columns.filter(c=>state.types[c]==="catégorielle"),dates=state.columns.filter(c=>state.types[c]==="date"),b=state.business||{};const strategic=b.primaryRevenue||b.primaryVolume||b.primaryFinancial||b.primaryResult||b.primaryRate||nums.sort((a,c)=>rolePriority(c)-rolePriority(a))[0];options("distributionColumn",nums,$("distributionColumn").value||strategic);options("statsColumn",nums,$("statsColumn").value||strategic);options("categoryColumn",cats,$("categoryColumn").value||b.primaryDimension||b.primaryStatus||cats[0]);options("scatterX",nums,$("scatterX").value||state.correlations[0]?.a||strategic||nums[0]);options("scatterY",nums,$("scatterY").value||state.correlations[0]?.b||nums.find(c=>c!==strategic)||nums[0]);options("dateColumn",dates,$("dateColumn").value||b.primaryDate||dates[0]);options("timeMetric",nums,$("timeMetric").value||b.primaryRevenue||b.primaryVolume||state.timeSeries[0]?.metric||strategic);options("periodicDate",dates,$("periodicDate").value||b.primaryDate||dates[0]);options("periodicMetric",nums,$("periodicMetric").value||b.primaryRevenue||b.primaryVolume||state.timeSeries[0]?.metric||strategic)}

function renderBusinessDiagnostic(){
  const b=state.business;if(!b)return;
  const cards=[
    {icon:"ID",label:"Identifiant principal",value:b.primaryId||"Non détecté",note:b.primaryId?`${fmt(b.idDistinct,0)} entités distinctes · unicité ${pct(b.idUniqueness,1)}`:"Nécessaire pour dédoublonner et suivre les entités."},
    {icon:"REV",label:"Revenu / montant principal",value:b.primaryRevenue||b.primaryFinancial||"Non détecté",note:b.primaryRevenue?`Total ${fmt(b.revenueTotal,2)}`:b.primaryFinancial?`Total ${fmt(b.financialTotal,2)}`:"Aucune variable financière clairement nommée."},
    {icon:"VOL",label:"Volume d'activité",value:b.primaryVolume||"Nombre de lignes",note:b.primaryVolume?`Volume cumulé ${fmt(b.volumeTotal,2)}`:`${fmt(state.data.length,0)} enregistrements utilisés par défaut.`},
    {icon:"DATE",label:"Date de référence",value:b.primaryDate||"Non détectée",note:b.range?b.range.detail:"Tendances et prévisions indisponibles sans date."},
    {icon:"DIM",label:"Dimension principale",value:b.primaryDimension||"Non détectée",note:b.primaryDimension?businessValue(b.primaryDimension):"Ajoutez client, produit, agence, région ou service."},
    {icon:"STAT",label:"Statut principal",value:b.primaryStatus||"Non détecté",note:b.primaryStatus?businessValue(b.primaryStatus):"Utile pour suivre les étapes et situations."},
    {icon:"CST",label:"Coût / dépense",value:b.primaryCost||"Non détecté",note:b.primaryCost?businessValue(b.primaryCost):"Nécessaire pour analyser l'efficience."},
    {icon:"OBJ",label:"Objectif / résultat",value:b.primaryTarget||b.primaryResult||"Non détecté",note:b.primaryTarget||b.primaryResult?businessValue(b.primaryTarget||b.primaryResult):"Ajoutez cible et réalisation pour mesurer l'atteinte."}
  ];
  $("businessMetricCards").innerHTML=cards.map(x=>`<div class="business-card"><div class="role-icon">${esc(x.icon)}</div><div class="business-label">${esc(x.label)}</div><div class="business-value">${esc(x.value)}</div><div class="business-note">${esc(x.note)}</div></div>`).join("");
  const groups=structuredVariableGroups();
  $("variableFamilySummary").innerHTML=groups.map(([key,cols])=>{const fam=VARIABLE_FAMILIES[key];return`<div class="family-summary-card" style="--family-color:${fam.color}"><div class="family-count">${cols.length}</div><div class="family-name">${esc(fam.label)}</div><div class="family-note">${esc(fam.description)}</div></div>`}).join("")||'<div class="empty" style="grid-column:1/-1;min-height:90px">Aucune famille de variables détectée.</div>';
  $("variableFamilyGrid").innerHTML=groups.map(([key,cols])=>{const fam=VARIABLE_FAMILIES[key],visible=cols.slice(0,8);return`<section class="variable-family-card" style="--family-color:${fam.color}"><div class="variable-family-head"><div><h3>${esc(fam.label)}</h3><p>${esc(fam.description)}</p></div><span class="variable-family-count">${cols.length}</span></div><div class="family-variable-list">${visible.map(c=>{const imp=importanceInfo(c),complete=100-state.missing[c];return`<div class="family-variable"><div><div class="family-variable-name">${esc(c)}</div><div class="family-variable-meta"><span class="role-pill">${esc(state.roles[c])}</span> · ${esc(state.types[c])} · ${pct(complete,0)}</div><span class="aggregation-pill">${esc(aggregationSuggestion(c))}</span></div><div class="family-variable-value"><strong>${esc(businessValue(c))}</strong>${esc(decisionUse(c))} · ${esc(imp.label)}</div></div>`}).join("")}${cols.length>visible.length?`<div class="family-variable"><div class="family-variable-name">+ ${cols.length-visible.length} autre(s) variable(s)</div><div class="family-variable-value">Voir le dictionnaire complet</div></div>`:""}</div></section>`}).join("")||'<div class="empty" style="grid-column:1/-1">Aucune architecture de variables disponible.</div>';
  const ordered=[...state.columns].sort((a,c)=>rolePriority(c)-rolePriority(a)||a.localeCompare(c,"fr")).slice(0,24);
  $("businessVariablesTable").innerHTML=ordered.map(c=>{const imp=importanceInfo(c),fam=variableFamily(c);return`<tr><td><strong>${esc(c)}</strong></td><td style="color:${fam.color};font-weight:800">${esc(fam.label)}</td><td><span class="role-pill">${esc(state.roles[c])}</span></td><td><span class="priority-dot ${imp.className}"></span><span class="importance ${imp.className}">${imp.label}</span></td><td>${esc(aggregationSuggestion(c))}</td><td>${esc(businessValue(c))}</td></tr>`}).join("");
  $("businessNarrative").textContent=businessNarrativeText()+` La structure comprend ${groups.length} famille(s) de variables. Les clés et mesures prioritaires sont séparées des axes de comparaison afin d'éviter de sommer ou de moyenner des identifiants.`;
  const checks=[["Identifiant",!!b.primaryId],["Revenu",!!b.primaryRevenue],["Montant",!!b.primaryFinancial],["Volume",!!b.primaryVolume],["Date",!!b.primaryDate],["Dimension",!!b.primaryDimension],["Statut",!!b.primaryStatus],["Objectif",!!b.primaryTarget],["Résultat",!!b.primaryResult]];
  const detected=checks.filter(x=>x[1]).length;$("businessCoverageBadge").textContent=`${detected}/${checks.length} familles utiles`;$("businessCoverageBadge").className=`badge ${detected>=7?"success":detected>=4?"warn":"danger"}`;
  $("businessCoverage").innerHTML=checks.map(([label,ok])=>`<span class="coverage-chip ${ok?"detected":"missing"}">${ok?"✓":"＋"} ${esc(label)}</span>`).join("")
}

function renderOverview(){const roleCounts={};state.columns.forEach(c=>{const label=state.roles[c]||"Autre";roleCounts[label]=(roleCounts[label]||0)+1});const entries=Object.entries(roleCounts).sort((a,b)=>(ROLE_META[Object.keys(ROLE_META).find(k=>ROLE_META[k].label===b[0])]?.priority||0)-(ROLE_META[Object.keys(ROLE_META).find(k=>ROLE_META[k].label===a[0])]?.priority||0)).slice(0,12).reverse();Plotly.newPlot("typeChart",[{x:entries.map(x=>x[1]),y:entries.map(x=>x[0]),type:"bar",orientation:"h",marker:{color:entries.map((_,i)=>activePalette.colors[i%activePalette.colors.length])},text:entries.map(x=>x[1]),textposition:"auto",hovertemplate:"%{y}<br>%{x} variable(s)<extra></extra>"}],{...plotLayout(),xaxis:{title:"Nombre de variables",dtick:1,gridcolor:"#e7edf5"},margin:{l:180,r:25,t:18,b:45}},plotConfig());const worst=[...state.columns].sort((a,b)=>state.missing[b]-state.missing[a]).slice(0,12).reverse();Plotly.newPlot("missingChart",[{x:worst.map(c=>state.missing[c]),y:worst,type:"bar",orientation:"h",marker:{color:worst.map(c=>state.missing[c]>=20?"#dc2626":state.missing[c]>=5?"#d97706":activePalette.accent)},text:worst.map(c=>pct(state.missing[c],1)),textposition:"auto"}],{...plotLayout(),xaxis:{title:"Valeurs manquantes (%)",range:[0,Math.max(10,...worst.map(c=>state.missing[c]))*1.15],gridcolor:"#e7edf5"},margin:{l:150,r:25,t:20,b:50}},plotConfig());renderDistribution("distributionChart",$("distributionColumn").value);renderBusinessDiagnostic();const f=analysisFacts(),b=f.business,q=state.quality.score,anRate=100*state.anomalies.length/state.data.length;$("decisionCards").innerHTML=[{v:b?.primaryRevenue?fmtCompact(b.revenueTotal,1):b?.primaryFinancial?fmtCompact(b.financialTotal,1):"—",t:b?.primaryRevenue?"Revenu total":"Montant principal",p:b?.primaryRevenue||b?.primaryFinancial||"Aucune mesure financière"},{v:fmtCompact(b?.volumeTotal??state.data.length,1),t:"Volume d'activité",p:b?.primaryVolume||"Nombre d'enregistrements"},{v:b?.primaryId?fmtCompact(b.idDistinct,1):"—",t:"Entités distinctes",p:b?.primaryId?`${b.primaryId} · ${pct(b.idUniqueness,0)} unique`:"Aucun identifiant fiable"}].map(x=>`<div class="decision-card"><h4>${esc(x.t)}</h4><div class="value">${esc(x.v)}</div><p>${esc(x.p)}</p></div>`).join("");$("decisionBadge").textContent=q>=80?"Base solide":q>=60?"Base exploitable sous réserve":"Risque élevé";$("decisionBadge").className=`badge ${q>=80?"success":q>=60?"warn":"danger"}`;const signals=[];if(b?.range)signals.push(["Période analysée",b.range.detail]);if(f.trend)signals.push(["Tendance prioritaire",`${f.trend.metric} · ${pct(f.trend.change,1)} sur la période`]);if(f.worst)signals.push(["Déficit d'information",`${f.worst} · ${pct(state.missing[f.worst],1)} manquant`]);signals.push(["Qualité / anomalies",`${pct(q,1)} · ${pct(anRate,1)} de lignes atypiques`]);signals.push(["Doublons",`${state.duplicates} ligne(s) identique(s)`]);$("keySignals").innerHTML=signals.map(s=>`<div class="signal"><span>${esc(s[0])}</span><strong>${esc(s[1])}</strong></div>`).join("")}
function renderDistribution(id,col){if(!col||!state.stats[col])return emptyPlot(id,"Aucune variable numérique.");const v=state.stats[col].values;Plotly.newPlot(id,[{x:v,type:"histogram",nbinsx:Math.min(45,Math.max(12,Math.round(Math.sqrt(v.length)))),marker:{color:activePalette.accent,opacity:.82},name:"Fréquence"},{x:[state.stats[col].median,state.stats[col].median],y:[0,Math.max(1,v.length/8)],mode:"lines",line:{color:"#dc2626",dash:"dash",width:2},name:"Médiane"}],{...plotLayout(),barmode:"overlay",xaxis:{title:col,gridcolor:"#e7edf5"},yaxis:{title:"Fréquence",gridcolor:"#e7edf5"},legend:{orientation:"h",y:1.08}},plotConfig())}
function renderExecutive(){$("audienceBadge").textContent=audienceLabel();$("executiveNarrative").textContent=executiveNarrative();const f=analysisFacts(),b=f.business,items=[];if(b?.primaryRevenue)items.push(["01","Revenu principal",`« ${b.primaryRevenue} » totalise ${fmt(b.revenueTotal,2)} sur la période.`]);else if(b?.primaryFinancial)items.push(["01","Montant principal",`« ${b.primaryFinancial} » totalise ${fmt(b.financialTotal,2)}.`]);items.push(["02","Volume d'activité",b?.primaryVolume?`« ${b.primaryVolume} » atteint ${fmt(b.volumeTotal,2)}.`:`${fmt(state.data.length,0)} lignes sont utilisées comme volume d'enregistrements.`]);items.push(["03","Identifiants et entités",b?.primaryId?`« ${b.primaryId} » contient ${fmt(b.idDistinct,0)} valeurs distinctes (${pct(b.idUniqueness,1)} d'unicité).`:"Aucune clé principale fiable n'a été détectée."]);if(b?.range)items.push(["04","Période couverte",`${b.range.detail}, à partir de « ${b.primaryDate} ».`]);items.push(["05","Fiabilité de la base",`Qualité ${pct(state.quality.score,1)}, complétude ${pct(state.quality.completeness,1)}, ${state.anomalies.length} anomalie(s) et ${state.duplicates} doublon(s).`]);if(f.trend)items.push(["06","Évolution prioritaire",`« ${f.trend.metric} » varie de ${pct(f.trend.change,1)} sur la période observée.`]);$("executiveInsights").innerHTML=items.map(i=>`<div class="insight"><div class="insight-icon">${i[0]}</div><div><strong>${esc(i[1])}</strong><p>${esc(i[2])}</p></div></div>`).join("");const pillars=[{t:"Ce que les données mesurent",p:[b?.primaryRevenue&&`revenu (${b.primaryRevenue})`,b?.primaryVolume&&`volume (${b.primaryVolume})`,b?.primaryId&&`entités (${b.primaryId})`,b?.primaryDate&&`temps (${b.primaryDate})`].filter(Boolean).join(" · ")||"La structure métier reste insuffisamment explicite."},{t:"Ce qui limite la preuve",p:!b?.primaryId||!b?.primaryDate?"L'absence d'une clé ou d'une date fiable limite le suivi longitudinal et les comparaisons.":state.quality.score<80?"La qualité et la complétude réduisent la portée de certaines conclusions.":"La base est robuste, mais une validation métier demeure nécessaire."},{t:"Ce qu'il faut décider",p:state.recommendations[0]?.description||"Formaliser les KPI prioritaires et leurs règles de calcul."}];$("executivePillars").innerHTML=pillars.map(x=>`<div class="decision-card"><h3>${esc(x.t)}</h3><p>${esc(x.p)}</p></div>`).join("");const methods=[['01','Classification métier','Identification des revenus, volumes, montants, coûts, dates, identifiants et dimensions.'],['02','Statistiques robustes','Sommes, moyennes, quartiles, dispersion, asymétrie et détection par médiane/MAD.'],['03','Relations et tendances','Corrélations, régressions exploratoires, comparaisons mensuelles et annuelles.'],['04','Analyse multivariée','PCA, K-means et anomalies pour identifier les profils et signaux atypiques.']];$("methodGrid").innerHTML=methods.map(m=>`<div class="method-card"><div class="num">${m[0]}</div><h3>${m[1]}</h3><p>${m[2]}</p></div>`).join("")}
function renderQuality(){const q=state.quality;$("qualityRingText").textContent=fmt(q.score,0);$("qualityRing").style.background=`conic-gradient(${activePalette.accent} ${q.score*3.6}deg,#e8edf5 0deg)`;$("qualityNarrative").textContent=q.score>=85?"La base présente une qualité élevée. Elle peut soutenir un reporting régulier, sous réserve de contrôles métier et de traçabilité.":q.score>=70?"La base est exploitable, mais plusieurs corrections ciblées amélioreront sensiblement la fiabilité des conclusions.":q.score>=50?"La qualité est fragile. Les résultats doivent être utilisés comme diagnostic exploratoire avant décision définitive.":"La qualité est critique. La priorité doit être donnée à la fiabilisation avant toute interprétation avancée.";const metrics=[['Complétude',q.completeness],['Unicité',q.uniqueness],['Cohérence',q.consistency],['Santé des anomalies',q.anomalyHealth]];$("qualityMetrics").innerHTML=metrics.map(m=>`<div class="metric-line"><div><span>${m[0]}</span><strong>${pct(m[1],1)}</strong></div><div class="progress"><span style="width:${m[1]}%"></span></div></div>`).join("");Plotly.newPlot("qualityRiskChart",[{type:"scatterpolar",r:metrics.map(m=>m[1]).concat(metrics[0][1]),theta:metrics.map(m=>m[0]).concat(metrics[0][0]),fill:"toself",line:{color:activePalette.accent},fillcolor:activePalette.accent+"33"}],{...plotLayout(),polar:{radialaxis:{visible:true,range:[0,100],gridcolor:"#dfe6ef"}},showlegend:false,margin:{l:45,r:45,t:25,b:25}},plotConfig());const rows=[...state.columns].sort((a,b)=>rolePriority(b)-rolePriority(a)).map(c=>{const st=state.stats[c],miss=state.missing[c],distinct=state.unique[c],complete=100-miss,anom=st?st.outliers:0,uniq=state.data.length?100*distinct/state.data.length:0,risk=miss>=20||anom>Math.max(5,state.data.length*.08)?"Élevé":miss>=5||anom>0?"Moyen":"Faible",cls=risk==="Élevé"?"high":risk==="Moyen"?"medium":"low";return`<tr><td><strong>${esc(c)}</strong></td><td><span class="role-pill">${esc(state.roles[c])}</span></td><td>${esc(state.types[c])}</td><td>${esc(roleUtility(c))}</td><td><div class="mini-bar"><span style="width:${complete}%"></span></div> ${pct(complete,1)}</td><td>${pct(uniq,1)}</td><td>${fmt(distinct,0)}</td><td>${fmt(anom,0)}</td><td class="risk ${cls}">${risk}</td></tr>`}).join("");$("qualityTable").innerHTML=rows;$("anomalyTable").innerHTML=state.anomalies.slice(0,$("depth").value==="expert"?50:20).map(a=>`<tr><td>${a.index+1}</td><td>${fmt(a.score,2)}</td><td>${esc(a.contributors.join(", ")||"Profil multivarié")}</td><td>${a.missing}</td><td class="risk ${a.score>=3?"high":a.score>=2?"medium":"low"}">${a.score>=3?"Élevé":a.score>=2?"Moyen":"Modéré"}</td></tr>`).join("")||'<tr><td colspan="5">Aucune anomalie majeure détectée.</td></tr>'}
function distributionText(c){const s=state.stats[c];if(!s)return"Aucune analyse disponible.";const shape=Math.abs(s.skew)<.5?"relativement symétrique":s.skew>0?"asymétrique vers les valeurs élevées":"asymétrique vers les valeurs faibles",disp=s.cv<15?"faible":s.cv<35?"modérée":"forte",out=s.outliers?`${s.outliers} valeur(s) atypique(s) selon la règle de l'IQR.`:"Aucune valeur atypique selon la règle de l'IQR.";return`« ${c} » présente une moyenne de ${fmt(s.mean,2)} et une médiane de ${fmt(s.median,2)}. La dispersion relative est ${disp} (CV ${pct(s.cv,1)}), la distribution est ${shape} (asymétrie ${fmt(s.skew,2)}). ${out}`}
function renderDescriptive(){const c=$("statsColumn").value;renderDistribution("statsHistogram",c);if(c&&state.stats[c])Plotly.newPlot("boxChart",[{y:state.stats[c].values,type:"box",name:c,boxpoints:"outliers",marker:{color:activePalette.accent},line:{color:activePalette.accent}}],{...plotLayout(),yaxis:{title:c,gridcolor:"#e7edf5"}},plotConfig());else emptyPlot("boxChart","Aucune variable numérique.");$("distributionNarrative").textContent=distributionText(c);$("statsTable").innerHTML=Object.entries(state.stats).map(([c,s])=>`<tr><td><strong>${esc(c)}</strong></td><td>${fmt(s.n,0)}</td><td>${fmt(s.mean,2)}</td><td>${fmt(s.median,2)}</td><td>${fmt(s.std,2)}</td><td>${pct(s.cv,1)}</td><td>${fmt(s.p10,2)}</td><td>${fmt(s.q1,2)}</td><td>${fmt(s.q3,2)}</td><td>${fmt(s.p90,2)}</td><td>${fmt(s.skew,2)}</td><td>${fmt(s.kurt,2)}</td><td>${fmt(s.outliers,0)}</td></tr>`).join("")||'<tr><td colspan="13">Aucune variable numérique.</td></tr>';renderCategory()}
function renderCategory(){const c=$("categoryColumn").value,s=state.catStats[c];if(!s){emptyPlot("categoryChart","Aucune variable catégorielle.");$("categoryNarrative").textContent="Aucune analyse catégorielle disponible.";$("categoryCards").innerHTML="";return}const top=s.counts.slice(0,15).reverse();Plotly.newPlot("categoryChart",[{x:top.map(x=>x[1]),y:top.map(x=>x[0]),type:"bar",orientation:"h",marker:{color:activePalette.colors},text:top.map(x=>fmt(x[1],0)),textposition:"auto"}],{...plotLayout(),margin:{l:150,r:25,t:20,b:45},xaxis:{title:"Nombre d'observations",gridcolor:"#e7edf5"}},plotConfig());const concentration=s.hhi>.25?"forte":s.hhi>.12?"modérée":"faible";$("categoryNarrative").textContent=`La catégorie dominante est « ${s.dominant} » avec ${pct(s.dominantShare,1)} des observations. La concentration est ${concentration} (HHI ${fmt(s.hhi,3)}), tandis que l'entropie normalisée atteint ${pct(s.normalizedEntropy*100,1)}.`;$("categoryCards").innerHTML=[['Modalités',fmt(s.distinct,0)],['Catégorie dominante',s.dominant],['Part dominante',pct(s.dominantShare,1)],['Diversité',pct(s.normalizedEntropy*100,1)]].map(x=>`<div class="decision-card"><h4>${x[0]}</h4><div class="value" style="font-size:18px">${esc(x[1])}</div></div>`).join("")}
function renderPeriodicStatistics(){const d=$("periodicDate")?.value,m=$("periodicMetric")?.value;if(!d||!m||state.types[d]!=="date"||state.types[m]!=="numérique"){["monthlyVolumeChart","monthlyDispersionChart","annualSummaryChart","seasonalityChart"].forEach(id=>emptyPlot(id,"Une date et une mesure numérique sont nécessaires."));$("periodNarrative").textContent="L'analyse périodique nécessite au moins une variable de date et une mesure numérique.";$("periodInsights").innerHTML='<div class="empty" style="grid-column:1/-1">Aucune analyse périodique.</div>';return}const a=periodicAnalysis(d,m);state.periodic=a;if(!a){return}$("periodCount").textContent=fmt(a.totalRecords,0);$("periodVolume").textContent=fmt(a.totalVolume,2);$("periodMonthlyMean").textContent=fmt(a.monthlyMean,2);$("periodMonthlyStd").textContent=fmt(a.monthlyStd,2);$("periodAnnualGrowth").textContent=pct(a.growth,1);$("periodAnnualGrowth").className=`value ${Number.isFinite(a.growth)?a.growth>0?"positive":a.growth<0?"negative":"neutral":"neutral"}`;$("periodBestMonth").textContent=a.best.label;$("periodBestMonthNote").textContent=fmt(a.best.sum,2);$("periodCoverageBadge").textContent=`${a.first.label} → ${a.last.label} · ${a.yearly.length} année(s)`;$("periodNarrative").textContent=periodicNarrative(a);const x=a.monthly.map(r=>r.label),sums=a.monthly.map(r=>r.sum),counts=a.monthly.map(r=>r.count),ma=a.movingAverage;Plotly.newPlot("monthlyVolumeChart",[{x,y:sums,type:"bar",name:"Volume",marker:{color:activePalette.accent},hovertemplate:"%{x}<br>Volume : %{y:,.2f}<extra></extra>"},{x,y:counts,type:"scatter",mode:"lines+markers",name:"Nombre",yaxis:"y2",line:{color:activePalette.accent2,width:3},marker:{size:6}},{x,y:ma,type:"scatter",mode:"lines",name:"Moyenne mobile 3 mois",line:{color:activePalette.primary,dash:"dot",width:2},connectgaps:false}],{...plotLayout(),barmode:"group",xaxis:{title:"Mois",gridcolor:"#e7edf5",tickangle:-35},yaxis:{title:`Volume · ${m}`,gridcolor:"#e7edf5"},yaxis2:{title:"Nombre",overlaying:"y",side:"right",showgrid:false},legend:{orientation:"h",y:1.12},margin:{l:65,r:65,t:45,b:85}},plotConfig());Plotly.newPlot("monthlyDispersionChart",[{x,y:a.monthly.map(r=>r.mean),type:"scatter",mode:"lines+markers",name:"Moyenne",line:{color:activePalette.accent,width:3},marker:{size:7},error_y:{type:"data",array:a.monthly.map(r=>Number.isFinite(r.std)?r.std:0),visible:true,color:activePalette.accent2,thickness:1.5,width:4}},{x,y:a.monthly.map(r=>r.median),type:"scatter",mode:"lines",name:"Médiane",line:{color:activePalette.primary2,dash:"dash",width:2}}],{...plotLayout(),xaxis:{title:"Mois",gridcolor:"#e7edf5",tickangle:-35},yaxis:{title:`Niveau par observation · ${m}`,gridcolor:"#e7edf5"},legend:{orientation:"h",y:1.12},margin:{l:65,r:25,t:45,b:85}},plotConfig());Plotly.newPlot("annualSummaryChart",[{x:a.yearly.map(r=>r.label),y:a.yearly.map(r=>r.sum),type:"bar",name:"Volume annuel",marker:{color:a.yearly.map((_,i)=>activePalette.colors[i%activePalette.colors.length])},text:a.yearly.map(r=>fmt(r.sum,1)),textposition:"auto"},{x:a.yearly.map(r=>r.label),y:a.yearly.map(r=>r.count),type:"scatter",mode:"lines+markers",name:"Nombre",yaxis:"y2",line:{color:activePalette.primary,width:3},marker:{size:8}}],{...plotLayout(),xaxis:{title:"Année",gridcolor:"#e7edf5"},yaxis:{title:`Volume annuel · ${m}`,gridcolor:"#e7edf5"},yaxis2:{title:"Nombre",overlaying:"y",side:"right",showgrid:false},legend:{orientation:"h",y:1.12},margin:{l:65,r:65,t:45,b:55}},plotConfig());const seas=a.seasonality.filter(r=>Number.isFinite(r.averageMonthlyVolume));Plotly.newPlot("seasonalityChart",[{x:seas.map(r=>r.label),y:seas.map(r=>r.averageMonthlyVolume),type:"bar",name:"Volume mensuel moyen",marker:{color:seas.map((_,i)=>activePalette.colors[i%activePalette.colors.length])}},{x:seas.map(r=>r.label),y:seas.map(r=>r.mean),type:"scatter",mode:"lines+markers",name:"Moyenne par observation",yaxis:"y2",line:{color:activePalette.primary,width:2.5}}],{...plotLayout(),xaxis:{title:"Mois de l'année",gridcolor:"#e7edf5"},yaxis:{title:"Volume mensuel moyen",gridcolor:"#e7edf5"},yaxis2:{title:"Moyenne par observation",overlaying:"y",side:"right",showgrid:false},legend:{orientation:"h",y:1.12},margin:{l:65,r:70,t:45,b:55}},plotConfig());const trendChange=a.first.sum!==0?100*(a.last.sum-a.first.sum)/Math.abs(a.first.sum):NaN,largestRise=a.monthly.filter(r=>Number.isFinite(r.mom)).sort((x,y)=>y.mom-x.mom)[0],largestFall=a.monthly.filter(r=>Number.isFinite(r.mom)).sort((x,y)=>x.mom-y.mom)[0];$("periodInsights").innerHTML=[{t:"Tendance globale",v:pct(trendChange,1),p:`De ${a.first.label} à ${a.last.label}`},{t:"Volatilité",v:pct(a.monthlyCV,1),p:`Coefficient de variation des volumes mensuels`},{t:"Plus forte hausse",v:largestRise?pct(largestRise.mom,1):"—",p:largestRise?.label||"Non calculable"},{t:"Plus forte baisse",v:largestFall?pct(largestFall.mom,1):"—",p:largestFall?.label||"Non calculable"}].map(x=>`<div class="decision-card"><h4>${esc(x.t)}</h4><div class="value">${esc(x.v)}</div><p>${esc(x.p)}</p></div>`).join("");$("monthlyStatsTable").innerHTML=a.monthly.map(r=>`<tr><td><strong>${esc(r.label)}</strong></td><td>${fmt(r.count,0)}</td><td>${fmt(r.valid,0)}</td><td>${fmt(r.sum,2)}</td><td>${fmt(r.mean,2)}</td><td>${fmt(r.median,2)}</td><td>${fmt(r.std,2)}</td><td>${fmt(r.variance,2)}</td><td>${pct(r.cv,1)}</td><td>${fmt(r.min,2)}</td><td>${fmt(r.max,2)}</td><td class="${r.mom>0?"positive":r.mom<0?"negative":"neutral"}">${pct(r.mom,1)}</td><td class="${r.yoy>0?"positive":r.yoy<0?"negative":"neutral"}">${pct(r.yoy,1)}</td></tr>`).join("");$("annualStatsTable").innerHTML=a.yearly.map(r=>`<tr><td><strong>${esc(r.label)}</strong></td><td>${fmt(r.count,0)}</td><td>${fmt(r.sum,2)}</td><td>${fmt(r.mean,2)}</td><td>${fmt(r.std,2)}</td><td>${pct(r.cv,1)}</td><td class="${r.yoy>0?"positive":r.yoy<0?"negative":"neutral"}">${pct(r.yoy,1)}</td></tr>`).join("")}
function renderRelationships(){const nums=state.columns.filter(c=>state.types[c]==="numérique").slice(0,18);if(nums.length>=2){const z=nums.map(a=>nums.map(b=>a===b?1:(state.correlations.find(x=>(x.a===a&&x.b===b)||(x.a===b&&x.b===a))?.r??null)));Plotly.newPlot("correlationChart",[{z,x:nums,y:nums,type:"heatmap",zmin:-1,zmax:1,colorscale:[[0,"#b91c1c"],[.5,"#ffffff"],[1,activePalette.accent]],text:z.map(r=>r.map(v=>v===null?"":fmt(v,2))),texttemplate:"%{text}",hovertemplate:"%{y} / %{x}<br>r=%{z:.3f}<extra></extra>"}],{...plotLayout(),margin:{l:120,r:25,t:20,b:110}},plotConfig())}else emptyPlot("correlationChart","Au moins deux variables numériques sont nécessaires.");$("corrBadge").textContent=`${state.correlations.length} relation(s)`;renderScatter();const cats=state.columns.filter(c=>state.types[c]==="catégorielle"&&state.unique[c]<=60).slice(0,12);if(cats.length>=2){const z=cats.map(a=>cats.map(b=>a===b?1:(state.cramer.find(x=>(x.a===a&&x.b===b)||(x.a===b&&x.b===a))?.v??0)));Plotly.newPlot("cramerChart",[{z,x:cats,y:cats,type:"heatmap",zmin:0,zmax:1,colorscale:[[0,"#ffffff"],[1,activePalette.accent]],text:z.map(r=>r.map(v=>fmt(v,2))),texttemplate:"%{text}"}],{...plotLayout(),margin:{l:110,r:20,t:20,b:100}},plotConfig())}else emptyPlot("cramerChart","Au moins deux variables catégorielles sont nécessaires.");const cards=[];state.correlations.slice(0,4).forEach(c=>cards.push({t:`${c.a} ↔ ${c.b}`,p:`Corrélation de Pearson ${fmt(c.r,2)} sur ${fmt(c.n,0)} observations. Relation ${Math.abs(c.r)>=.8?"très forte":Math.abs(c.r)>=.6?"forte":Math.abs(c.r)>=.4?"modérée":"faible"}.`}));state.cramer.slice(0,2).forEach(c=>cards.push({t:`${c.a} ↔ ${c.b}`,p:`Association catégorielle V=${fmt(c.v,2)}, ${c.v>=.5?"forte":c.v>=.3?"modérée":"faible"}.`}));$("relationshipCards").innerHTML=cards.length?cards.map((x,i)=>`<div class="recommendation"><span class="priority">Signal ${i+1}</span><h3>${esc(x.t)}</h3><p>${esc(x.p)}</p></div>`).join(""):'<div class="empty" style="grid-column:1/-1">Aucune relation remarquable.</div>'}
function renderScatter(){const xcol=$("scatterX").value,ycol=$("scatterY").value;if(!state.stats[xcol]||!state.stats[ycol])return emptyPlot("scatterChart","Aucune relation disponible.");const x=[],y=[];for(const r of state.data.slice(0,6000)){const a=smartNumber(r[xcol]),b=smartNumber(r[ycol]);if(a!==null&&b!==null){x.push(a);y.push(b)}}const reg=linearRegression(x,y),traces=[{x,y,type:"scatter",mode:"markers",marker:{size:7,opacity:.55,color:activePalette.accent},name:"Observations"}];if(reg){const xx=[Math.min(...x),Math.max(...x)];traces.push({x:xx,y:xx.map(v=>reg.intercept+reg.slope*v),mode:"lines",line:{color:"#dc2626",width:3},name:"Régression"})}Plotly.newPlot("scatterChart",traces,{...plotLayout(),xaxis:{title:xcol,gridcolor:"#e7edf5"},yaxis:{title:ycol,gridcolor:"#e7edf5"},legend:{orientation:"h",y:1.08}},plotConfig());$("regressionNarrative").textContent=reg?`Sur ${fmt(reg.n,0)} observations, une hausse d'une unité de « ${xcol} » est associée à une variation moyenne de ${fmt(reg.slope,3)} unité de « ${ycol} ». Le modèle linéaire explique ${pct(reg.r2*100,1)} de la variance observée (R²). Cette relation est exploratoire et ne démontre pas un effet causal.`:"Régression non calculable."}
function renderTemporal(){const d=$("dateColumn").value,m=$("timeMetric").value;if(!d||!m||state.types[d]!=="date"||state.types[m]!=="numérique"){emptyPlot("timeChart","Aucune dimension temporelle détectée.");$("timeNarrative").textContent="L'analyse temporelle nécessite une date et une mesure numérique.";$("trendCards").innerHTML='<div class="empty" style="grid-column:1/-1">Aucune tendance.</div>';return}const points=aggregateTime(d,m);if(points.length<2){emptyPlot("timeChart","Pas assez de périodes.");return}const x=points.map(p=>p.date),y=points.map(p=>p.sum),reg=linearRegression(y.map((_,i)=>i),y),trend=y.map((_,i)=>reg?reg.intercept+reg.slope*i:null);Plotly.newPlot("timeChart",[{x,y,type:"scatter",mode:"lines+markers",line:{color:activePalette.accent,width:3},marker:{size:7},name:"Valeur agrégée"},{x,y:trend,type:"scatter",mode:"lines",line:{color:"#dc2626",dash:"dash",width:2},name:"Tendance"}],{...plotLayout(),xaxis:{title:d,gridcolor:"#e7edf5"},yaxis:{title:m,gridcolor:"#e7edf5"},legend:{orientation:"h",y:1.08}},plotConfig());const change=y[0]!==0?100*(y.at(-1)-y[0])/Math.abs(y[0]):NaN,changes=y.slice(1).map((v,i)=>y[i]?100*(v-y[i])/Math.abs(y[i]):0),vol=sd(changes);$("timeNarrative").textContent=`Entre la première et la dernière période, « ${m} » évolue de ${pct(change,1)}. La direction de tendance est ${reg.slope>0?"haussière":reg.slope<0?"baissière":"stable"}, avec une volatilité périodique estimée à ${pct(vol,1)}. Le R² de tendance atteint ${pct((reg.r2||0)*100,1)}.`;$("trendCards").innerHTML=state.timeSeries.slice(0,6).map(t=>`<div class="recommendation"><span class="priority">${t.slope>=0?"Hausse":"Baisse"}</span><h3>${esc(t.metric)}</h3><p>Variation ${pct(t.change,1)} · volatilité ${pct(t.volatility,1)} · R² ${pct(t.r2*100,1)}</p></div>`).join("")||'<div class="empty" style="grid-column:1/-1">Aucune tendance.</div>'}
function renderPCA(){if(!state.pca){emptyPlot("pcaChart","Au moins trois variables numériques et suffisamment de lignes complètes sont nécessaires.");$("pcaNarrative").textContent="PCA non calculable avec la structure actuelle.";return}const p=state.pca;Plotly.newPlot("pcaChart",[{x:p.scores.map(s=>s[0]),y:p.scores.map(s=>s[1]),type:"scattergl",mode:"markers",marker:{size:6,opacity:.55,color:activePalette.accent},text:p.complete.map(x=>`Ligne ${x.index+1}`),hovertemplate:"%{text}<br>PC1=%{x:.2f}<br>PC2=%{y:.2f}<extra></extra>"}],{...plotLayout(),xaxis:{title:`Composante 1 (${pct(p.explained[0],1)})`,gridcolor:"#e7edf5"},yaxis:{title:`Composante 2 (${pct(p.explained[1],1)})`,gridcolor:"#e7edf5"}},plotConfig());$("pcaNarrative").textContent=`Les deux premières composantes résument ${pct(p.explained[0]+p.explained[1],1)} de la variance des ${p.cols.length} variables numériques retenues. Une valeur faible indique que la structure est multidimensionnelle et ne peut pas être résumée par un seul graphique.`;if(state.clusters)renderClusters()}
function runClustering(){if(!state.pca)return alert("La segmentation nécessite au moins trois variables numériques et suffisamment de lignes complètes.");const k=clamp(Number($("clusterK").value)||3,2,8),result=kmeans(state.pca.scores,k),sil=silhouette(state.pca.scores,result.labels,k);state.clusters={k,...result,silhouette:sil};renderClusters()}
function renderClusters(){const p=state.pca,c=state.clusters,traces=[];for(let g=0;g<c.k;g++){const pts=p.scores.map((s,i)=>({s,i})).filter(x=>c.labels[x.i]===g);traces.push({x:pts.map(x=>x.s[0]),y:pts.map(x=>x.s[1]),type:"scattergl",mode:"markers",name:`Groupe ${g+1}`,marker:{size:7,opacity:.7,color:activePalette.colors[g%activePalette.colors.length]},text:pts.map(x=>`Ligne ${p.complete[x.i].index+1}`),hovertemplate:"%{text}<extra></extra>"})}Plotly.newPlot("pcaChart",traces,{...plotLayout(),xaxis:{title:`Composante 1 (${pct(p.explained[0],1)})`,gridcolor:"#e7edf5"},yaxis:{title:`Composante 2 (${pct(p.explained[1],1)})`,gridcolor:"#e7edf5"},legend:{orientation:"h",y:1.09}},plotConfig());const profiles=[];for(let g=0;g<c.k;g++){const ids=p.matrix.map((_,i)=>i).filter(i=>c.labels[i]===g);profiles.push(p.cols.map((_,j)=>mean(ids.map(i=>p.matrix[i][j]))))}Plotly.newPlot("clusterProfileChart",profiles.map((r,g)=>({z:[r],x:p.cols,y:[`Groupe ${g+1}`],type:"heatmap",showscale:g===0,colorscale:[[0,"#b91c1c"],[.5,"#fff"],[1,activePalette.accent]],zmin:-2,zmax:2,name:`Groupe ${g+1}`})),{...plotLayout(),margin:{l:85,r:25,t:15,b:110},yaxis:{automargin:true}},plotConfig());$("silhouetteBadge").textContent=`Silhouette ${fmt(c.silhouette,2)}`;$("silhouetteBadge").className=`badge ${c.silhouette>=.5?"success":c.silhouette>=.25?"warn":"danger"}`;const cards=[];for(let g=0;g<c.k;g++){const ids=c.labels.map((x,i)=>x===g?i:-1).filter(i=>i>=0),prof=profiles[g].map((v,j)=>({c:p.cols[j],v})).sort((a,b)=>Math.abs(b.v)-Math.abs(a.v)).slice(0,3);cards.push(`<div class="recommendation"><span class="priority">Groupe ${g+1}</span><h3>${fmt(ids.length,0)} observations</h3><p>${prof.map(x=>`${x.c}: ${x.v>=0?"au-dessus":"au-dessous"} de la moyenne (${fmt(x.v,1)}σ)`).join(" · ")}</p></div>`)}$("clusterSummary").innerHTML=`<div class="grid-2">${cards.join("")}</div>`}
function renderRecommendations(){state.recommendations=buildRecommendations();$("actionCount").textContent=`${state.recommendations.length} action(s)`;$("recommendationGrid").innerHTML=state.recommendations.map((r,i)=>`<div class="recommendation"><span class="priority">${esc(r.priority)}</span><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><div class="recommendation-meta"><span class="tag">Impact ${r.impact}/5</span><span class="tag">Effort ${r.effort}/5</span><span class="tag">${esc(r.horizon)}</span><span class="tag">${esc(r.owner)}</span></div></div>`).join("");Plotly.newPlot("impactEffortChart",[{x:state.recommendations.map(r=>r.effort),y:state.recommendations.map(r=>r.impact),text:state.recommendations.map(r=>r.title),mode:"markers+text",textposition:"top center",marker:{size:state.recommendations.map((_,i)=>18+i%3*3),color:state.recommendations.map((_,i)=>activePalette.colors[i%activePalette.colors.length]),opacity:.8,line:{color:"#fff",width:1}},hovertemplate:"%{text}<br>Effort %{x}/5<br>Impact %{y}/5<extra></extra>"}],{...plotLayout(),xaxis:{title:"Effort",range:[.5,5.5],dtick:1,gridcolor:"#e7edf5"},yaxis:{title:"Impact",range:[.5,5.5],dtick:1,gridcolor:"#e7edf5"},shapes:[{type:"line",x0:3,x1:3,y0:.5,y1:5.5,line:{color:"#94a3b8",dash:"dot"}},{type:"line",x0:.5,x1:5.5,y0:3,y1:3,line:{color:"#94a3b8",dash:"dot"}}]},plotConfig());const groups={"Court terme":state.recommendations.filter(r=>/0–|Immédiat/.test(r.horizon)),"Moyen terme":state.recommendations.filter(r=>/30–90|30–120|60–180/.test(r.horizon)),"Long terme":state.recommendations.filter(r=>/180|Long/.test(r.horizon))};$("roadmap").innerHTML=Object.entries(groups).map(([k,v])=>`<div class="decision-card"><h3>${k}</h3>${v.length?v.map(r=>`<div class="signal"><span>${esc(r.owner)}</span><strong>${esc(r.title)}</strong></div>`).join(""):"<p>Aucune action spécifique.</p>"}</div>`).join("")}
function renderData(){
  const limit=Math.min(25,state.data.length),cols=[...state.columns].sort((a,b)=>rolePriority(b)-rolePriority(a)).slice(0,18);$("previewBadge").textContent=`${limit} / ${fmt(state.data.length,0)} lignes`;$("dataPreview").innerHTML=`<table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join("")}</tr></thead><tbody>${state.data.slice(0,limit).map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const groups=structuredVariableGroups();
  $("dictionaryBadge").textContent=`${state.columns.length} variable${state.columns.length>1?"s":""}`;
  $("dictionaryFamilyNav").innerHTML=groups.map(([key,cols])=>{const fam=VARIABLE_FAMILIES[key];return`<span class="dictionary-chip" style="border-color:${fam.color}55;color:${fam.color}">${esc(fam.label)} · ${cols.length}</span>`}).join("");
  $("dictionaryTable").innerHTML=groups.map(([key,columns])=>{const fam=VARIABLE_FAMILIES[key];return`<tr class="family-table-row" style="--family-color:${fam.color}"><td colspan="10">${esc(fam.label)} — ${esc(fam.description)} (${columns.length})</td></tr>`+columns.map(c=>{const ex=[...new Set(state.data.map(r=>r[c]).filter(v=>!isMissing(v)).slice(0,80).map(String))].slice(0,3).join(" · "),imp=importanceInfo(c);return`<tr><td style="color:${fam.color};font-weight:800">${esc(fam.short)}</td><td><strong>${esc(c)}</strong></td><td><span class="role-pill">${esc(state.roles[c])}</span></td><td>${esc(state.types[c])}</td><td><span class="priority-dot ${imp.className}"></span>${esc(imp.label)}</td><td>${esc(aggregationSuggestion(c))}</td><td>${esc(roleUtility(c))}</td><td>${esc(ex)}</td><td>${fmt(state.unique[c],0)}</td><td>${pct(100-state.missing[c],1)} · ${esc(variableQualityLabel(c))}</td></tr>`}).join("")}).join("")||'<tr><td colspan="10">Aucune donnée.</td></tr>'
}

